/**
 * The metric justabill.vercel.drain.lines.
 *
 * Vercel log drain lines vercel-drain received, by shape and outcome.
 *
 * The census that checks the failure counting rule against production data (design 473).
 *
 * Instrument: counter. Unit: {line}. Stability: development.
 *
 * Attributes:
 *   - justabill.vercel.line.outcome (required)
 *   - justabill.vercel.log.type (required)
 *   - justabill.vercel.source (required)
 *   - justabill.vercel.status_class (required)
 */
export const METRIC_VERCEL_DRAIN_LINES = "justabill.vercel.drain.lines";

/** The UCUM unit of justabill.vercel.drain.lines. */
export const METRIC_VERCEL_DRAIN_LINES_UNIT = "{line}";

/** The description of justabill.vercel.drain.lines. */
export const METRIC_VERCEL_DRAIN_LINES_DESCRIPTION = "Vercel log drain lines vercel-drain received, by shape and outcome.";

/**
 * The metric justabill.vercel.function.failures.
 *
 * Web function requests that crashed, timed out or failed, counted once each from Vercel's drain lines.
 *
 * Deduplicated by Vercel's request ID for 15 minutes on each vercel-drain replica, so a request whose lines reach both replicas can count twice. Carries no path, host, request ID or IP. Design docs/design/473-vercel-function-failures.md.
 *
 * Instrument: counter. Unit: {request}. Stability: development.
 *
 * Attributes:
 *   - http.response.status_code ({"conditionally_required": "When the line carries a valid HTTP status."})
 *   - justabill.vercel.failure.kind (required)
 */
export const METRIC_VERCEL_FUNCTION_FAILURES = "justabill.vercel.function.failures";

/** The UCUM unit of justabill.vercel.function.failures. */
export const METRIC_VERCEL_FUNCTION_FAILURES_UNIT = "{request}";

/** The description of justabill.vercel.function.failures. */
export const METRIC_VERCEL_FUNCTION_FAILURES_DESCRIPTION = "Web function requests that crashed, timed out or failed, counted once each from Vercel's drain lines.";

