/** The description of justabill.web.fixture_fallback. */
export const METRIC_WEB_FIXTURE_FALLBACK_DESCRIPTION = "Pages the web app rendered from example fixtures because the API call failed.";

/**
 * The event name justabill.pipeline.job.finished.
 *
 * A pipeline job run finished.
 *
 * Emitted once per run by the scheduler and backfill, whatever the outcome.
 *
 * Stability: development.
 *
 * Attributes:
 *   - justabill.job.duration (required)
 *   - justabill.job.items.failed (recommended)
 *   - justabill.job.items.ok (recommended)
 *   - justabill.job.name (required)
 *   - justabill.job.outcome (required)
 */
export const EVENT_PIPELINE_JOB_FINISHED = "justabill.pipeline.job.finished";

